for a,b,c in [(42,40,41),(48,40,42),(48,40,41),(48,40,15),(48,40,16),(40,42,43)]:
 u=p[a-1]-p[b-1];v=p[c-1]-p[b-1];print(a,b,c,'angle',np.degrees(np.arccos(np.clip(np.dot(u,v)/np.linalg.norm(u)/np.linalg.norm(v),-1,1))))
m=Chem.MolFromMolFile('organic.mol',removeHs=False)
